// ===========================================================================================
// USEINTERVIEW.JS — Custom React Hook for Interview Operations & State.
//
// WHAT THIS HOOK DOES:
//   1. Subscribes to InterviewContext (providing global report, reports, and loading state).
//   2. Exposes operations to:
//      - generateReport: Uploads resume + job description to backend and receives structured JSON.
//      - getReportById: Fetches a single interview report by its MongoDB ID.
//      - getReports: Fetches all interview reports generated by the logged-in user.
//      - getResumePdf: Calls AI resume endpoint, receives binary PDF blob, triggers browser file download.
//   3. Auto-fetches data based on route parameters:
//      - If URL has :interviewId (on /interview/:interviewId), automatically fetches that report.
//      - Otherwise (on /), automatically fetches the list of past reports.
// ===========================================================================================

// Import API service functions that make HTTP requests to the Express backend.
import { getAllInterviewReports, generateInterviewReport, getInterviewReportById, generateResumePdf } from "../services/interview.api";

// Import useContext and useEffect hooks from React.
// useContext accesses the InterviewContext value.
// useEffect synchronizes report fetching with changes in the route URL.
import { useContext, useEffect } from "react";

// Import the InterviewContext object to subscribe to shared interview state.
import { InterviewContext } from "../interview.context";

// Import useParams from react-router to extract URL parameters (e.g. interviewId from /interview/:interviewId).
import { useParams } from "react-router";

// ── Custom Hook Definition ───────────────────────────────────────────────────
export const useInterview = () => {

    // Consume the InterviewContext provided by <InterviewProvider> in App.jsx.
    const context = useContext(InterviewContext);

    // Extract dynamic route parameter :interviewId if currently on the /interview/:interviewId route.
    const { interviewId } = useParams();

    // Guard against calling this hook outside the provider hierarchy.
    if (!context) {
        throw new Error("useInterview must be used within an InterviewProvider");
    }

    // Destructure state variables and setters from the context value.
    const { loading, setLoading, report, setReport, reports, setReports } = context;

    // ── 1. Generate Interview Report ─────────────────────────────────────────
    // Receives { jobDescription, selfDescription, resumeFile } from the Home page form.
    // Calls POST /api/interview/ (multipart/form-data), updates context with new report, and returns it.
    const generateReport = async ({ jobDescription, selfDescription, resumeFile }) => {
        // Set loading flag to true so the UI displays the loading animation.
        setLoading(true);
        let response = null;
        try {
            // Send request to backend via the interview API service.
            response = await generateInterviewReport({ jobDescription, selfDescription, resumeFile });

            // Store the returned interviewReport object in global context.
            setReport(response.interviewReport);
        } catch (error) {
            // Log any API or network errors.
            console.error("Error generating report:", error);
        } finally {
            // Reset loading state once the request completes.
            setLoading(false);
        }

        // Return the report object so callers (e.g., Home.jsx) can navigate to the new report page.
        return response?.interviewReport;
    };

    // ── 2. Get Single Report By ID ───────────────────────────────────────────
    // Receives a MongoDB ObjectId string and fetches the full report data from the backend.
    const getReportById = async (interviewId) => {
        setLoading(true);
        let response = null;
        try {
            // GET /api/interview/report/:interviewId
            response = await getInterviewReportById(interviewId);

            // Save the retrieved report into context state for the Interview detail page.
            setReport(response.interviewReport);
        } catch (error) {
            console.error("Error fetching report by ID:", error);
        } finally {
            setLoading(false);
        }
        return response?.interviewReport;
    };

    // ── 3. Get All Reports for Current User ──────────────────────────────────
    // Fetches the array of all past reports created by the logged-in user.
    const getReports = async () => {
        setLoading(true);
        let response = null;
        try {
            // GET /api/interview/ (returns { interviewReports: [...] })
            response = await getAllInterviewReports();

            // Store list of reports in context state.
            setReports(response.interviewReports);
        } catch (error) {
            console.error("Error fetching all reports:", error);
        } finally {
            setLoading(false);
        }

        return response?.interviewReports;
    };

    // ── 4. Download Tailored Resume PDF ──────────────────────────────────────
    // Requests Gemini AI to generate an ATS-optimized HTML resume for this report,
    // converts it to PDF via Puppeteer on the backend, and triggers an in-browser file download.
    const getResumePdf = async (interviewReportId) => {
        setLoading(true);
        try {
            // Call backend endpoint which returns binary PDF data as an arraybuffer/blob.
            const response = await generateResumePdf({ interviewReportId });

            // Create a Blob from the binary PDF response.
            const url = window.URL.createObjectURL(new Blob([response], { type: "application/pdf" }));

            // Create a temporary hidden <a> anchor tag to trigger the browser's native file download.
            const link = document.createElement("a");
            link.href = url;
            link.setAttribute("download", `resume_${interviewReportId}.pdf`);

            // Append link to document, simulate user click, and cleanup.
            document.body.appendChild(link);
            link.click();
            link.remove();

            // Revoke the temporary blob URL to free memory.
            window.URL.revokeObjectURL(url);
        } catch (error) {
            console.error("Error downloading resume PDF:", error);
        } finally {
            setLoading(false);
        }
    };

    // ── 5. Route Synchronization Effect ──────────────────────────────────────
    // Whenever the route URL changes (detected via interviewId param):
    //   - If interviewId is present in URL (e.g. /interview/6789abc), fetch that specific report.
    //   - If no interviewId is present (e.g. / on the Home page), fetch all past user reports.
    useEffect(() => {
        if (interviewId) {
            getReportById(interviewId);
        } else {
            getReports();
        }
    }, [interviewId]); // Re-run effect whenever interviewId changes in the URL.

    // Return all reactive states and action functions for component consumption.
    return { loading, report, reports, generateReport, getReportById, getReports, getResumePdf };
};